  "Bu o'quvchi oy to'lovining kamida {percent}% ini to'lamagan. Shartnomaga ko'ra 2-darsdan boshlab shu qismi to'lanmaguncha darsga qo'yilmaydi. Agar u darsda o'tirsa va keyinroq to'lov qilsa ham, bu dars uchun sizga ish haqi yozilmaydi.": "Этот ученик не оплатил минимум {percent}% месячного платежа. По договору со 2-го занятия его не допускают на занятия, пока эта часть не оплачена. Если он всё же будет на занятии и оплатит позже, за это занятие вам зарплата не начисляется.",
  "Bu darsga kirishi uchun kamida {amount} so'm kerak. Oyni to'liq qoplamasa, qolgan qismi uchun to'lov va'dasi yoziladi.": "Чтобы попасть на это занятие, нужно внести не менее {amount} сум. Если месяц не будет оплачен полностью, на остаток запишется обещание платежа.",
  "Bu o'quvchi oylik to'lovni qilmagan. Shartnomaga ko'ra 2-darsdan boshlab to'lov qilinmaguncha darsga qo'yilmaydi. Agar u darsda o'tirsa va keyinroq to'lov qilsa ham, bu dars uchun sizga ish haqi yozilmaydi.": "Этот ученик не внёс ежемесячный платёж. По договору со 2-го занятия его не допускают на занятия, пока он не оплатит. Если он всё же будет на занятии и оплатит позже, за это занятие вам зарплата не начисляется.",

