  "Asl va yangi sanani tanlang": "Выберите исходную и новую дату",
  "Yangi sana asl sanadan keyin bo'lishi kerak": "Новая дата должна быть позже исходной",
  "Dars boshlanish vaqtini kiriting": "Укажите время начала занятия",
  "Bo'sh xonani tanlang": "Выберите свободную аудиторию",
