  // Groups — app activity tab
  "O'quvchilarning ilovadagi faolligi": "Активность учеников в приложении",
  "Veb, Android va iOS bir xil qoida bilan sanaladi": "Веб, Android и iOS считаются по одному правилу",
  "Guruhda faol o'quvchi yo'q": "В группе нет активных учеников",
