  "{n} nafarida akkaunt yo'q": "Нет аккаунта: {n}",
  "{n} nafari kirmagan": "Не заходили: {n}",
  "Hammasi kirgan": "Заходили все",
  "Tanlangan davrda kamida 10 soniya faol bo'lgan o'quvchilar.": "Ученики, которые были активны в выбранный период не менее 10 секунд.",
  "O'rtacha faol vaqt": "Среднее активное время",
  "kirganlar orasida, bir o'quvchiga": "среди заходивших, на одного ученика",
  "Faol vaqt: ilova ekranda ochiq va o'quvchi oxirgi 2 daqiqada biror harakat qilgan. Radio bunga kirmaydi.": "Активное время: приложение открыто на экране, и ученик за последние 2 минуты совершил какое-либо действие. Радио сюда не входит.",
  "birinchi urinishda · {n} savol": "с первой попытки · вопросов: {n}",
  "Har bir savol birinchi so'ralganda to'g'ri topilgani. Xatodan keyin qayta so'ralgandagi javob bu foizga kirmaydi.": "Вопрос засчитывается, если на него правильно ответили при первом показе. Ответ на повторный вопрос после ошибки в этот процент не входит.",
  "Tugatilgan darslar": "Пройденные уроки",
  "davrda, har dars bir marta": "за период, каждый урок один раз",
  "Davrda oxirigacha ishlangan turli darslar. Bitta darsni qayta ishlash qo'shimcha sanalmaydi.": "Разные уроки, пройденные за период до конца. Повторное прохождение одного урока дополнительно не считается.",
  "{n} o'quvchi tingladi": "Слушали: {n}",
  "Ovoz haqiqatan yangragan vaqt. Ekran yopiq bo'lsa ham sanaladi, lekin faol vaqtga qo'shilmaydi.": "Время, когда звук действительно воспроизводился. Считается и при закрытом экране, но к активному времени не добавляется.",
  // Groups — app activity table
  "Shug'ullangan kunlar": "Дни практики",
  "Shu kuni kamida bitta mashq qildi yoki kamida 5 daqiqa radio tingladi": "В этот день ученик выполнил хотя бы одно упражнение или слушал радио не менее 5 минут",
  "{n} savol": "Вопросов: {n}",
