  // Groups — app activity explainer
  "Raqamlar qanday hisoblanadi": "Как считаются цифры",
  "ilova ekranda ochiq va o'quvchi oxirgi 2 daqiqada biror harakat qilgan vaqt. Ochiq qoldirilgan tab sanalmaydi.": "приложение открыто на экране, и ученик за последние 2 минуты совершил какое-либо действие. Забытая открытая вкладка не считается.",
  "ovoz haqiqatan yangragan vaqt. Ekran yopiq bo'lsa ham sanaladi, faol vaqtga qo'shilmaydi.": "время, когда звук действительно воспроизводился. Считается и при закрытом экране, но к активному времени не добавляется.",
  "kamida bitta mashq javobi yoki kamida 5 daqiqa radio. Faqat ilovani ochish sanalmaydi.": "хотя бы один ответ на упражнение или не менее 5 минут радио. Просто открыть приложение недостаточно.",
  "Kunlar maxraji": "Знаменатель дней",
  "o'quvchi akkaunti yaratilgan yoki kuzatuv boshlangan kundan sanaladi.": "считается со дня создания аккаунта ученика или начала наблюдения.",
  "Kuzatuv {date} dan boshlangan.": "Наблюдение началось {date}.",
  "har bir savol birinchi so'ralganda to'g'ri topilgani. Xatodan keyin qayta so'ralgandagi javob bu foizga kirmaydi. O'quvchi natija ekranida ko'radigan raqam bilan bir xil ta'rif.": "каждый вопрос засчитывается, если ответ при первом показе верный. Ответ на повторный вопрос после ошибки в этот процент не входит. Определение то же, что и у числа на экране результата у ученика.",
  "darajadagi kurs darslaridan tugatilganlari; o'quvchi darajasi guruhnikidan past bo'lsa «Guruhdan orqada» belgisi.": "пройденные уроки курса на этом уровне; если уровень ученика ниже уровня группы, появляется отметка «Отстаёт от группы».",
  // Groups — app activity difficult items
  "Guruh qiynalayotgan so'z va gaplar": "Слова и предложения, которые даются группе тяжело",
  "Birinchi urinishdagi xato foizi bo'yicha · kamida 3 o'quvchi ishlagan": "По проценту ошибок с первой попытки · работали не менее 3 учеников",
  "Hali yetarli ma'lumot yo'q — kamida 3 o'quvchi bir xil so'z yoki gapni ishlashi kerak": "Данных пока недостаточно — не менее 3 учеников должны проработать одно и то же слово или предложение",
