  "Guruh faol emas ({status}). Davomat olish mumkin emas.": "Группа неактивна ({status}). Отметить посещаемость нельзя.",
  "Dars {start} da boshlanadi (Toshkent vaqti). Davomat dars boshlanishidan {n} daqiqa oldin ochiladi": "Занятие начинается в {start} (по ташкентскому времени). Отметка посещаемости открывается за {n} мин. до начала",
  "Dars vaqti tugagan ({start} – {end}, Toshkent vaqti). Davomat olish yopilgan": "Время занятия закончилось ({start} – {end}, по ташкентскому времени). Отметка посещаемости закрыта",
  "Dars davom etmoqda ({start} – {end}, Toshkent vaqti)": "Идёт занятие ({start} – {end}, по ташкентскому времени)",
  "To'lov qabul qilindi, lekin ro'yxatni yangilab bo'lmadi. Sahifani qayta yuklang": "Оплата принята, но список не удалось обновить. Перезагрузите страницу",
