  "Barcha o'quvchilarning holati belgilanishi shart. Belgilanmagan: {n} ta": "Нужно отметить всех учеников. Не отмечено: {n}",
  "Davomat muvaffaqiyatli saqlandi": "Посещаемость сохранена",
  "Orqaga": "Назад",
  "Davomat olib bo'lingan. Tahrirlash uchun administratorga murojaat qiling": "Посещаемость уже отмечена. Чтобы изменить её, обратитесь к администратору",
  "Dars tugagan — davomat olish yopilgan. Dars bo'lgan-bo'lmaganini «Davomat olinmagan darslar» ro'yxatida, «Jadval» yoki «Topshiriqlar»da belgilang.": "Занятие закончилось — отметка посещаемости закрыта. Было ли занятие, отметьте в списке «Занятия без отметки посещаемости», в «Расписании» или «Задачах».",
  "Oldindan belgilash rejimi — bugun kelmaydigan o'quvchini hozir belgilang. Dars vaqtida ustoz davomatni oladi; belgilangan o'quvchilar \"Sababli\" bo'lib turadi (pul yechilmaydi).": "Режим предварительной отметки — отметьте сейчас ученика, который сегодня не придёт. Во время занятия преподаватель отметит посещаемость; отмеченные ученики остаются «По уважительной причине» (деньги не списываются).",
  "Hozir to'liq davomat olish": "Отметить всю посещаемость сейчас",
