  "Bu o'quvchilar oylik to'lovni to'liq to'lamagan. «Shu oy» ustuni to'lov oyning nechta darsiga yetishini ko'rsatadi.": "Эти ученики не оплатили месяц полностью. Столбец «Этот месяц» показывает, на сколько занятий месяца хватает оплаты.",
  "Bu o'quvchilarning balansi manfiyga tushgan. Davomat olinishi davom etadi va har bir dars bahosi balansdan ushlanmoqda — to'lov qabul qilingach, ustozning oyligiga ham hisoblanadi.": "Баланс этих учеников ушёл в минус. Посещаемость продолжает отмечаться, и стоимость каждого занятия списывается с баланса — после оплаты она засчитывается и в зарплату преподавателя.",
