  "Barcha qarzdorlar — hozir o'qiyotgani ham, ketgani ham.": "Все должники — и те, кто сейчас учится, и выбывшие.",
  "Qarz oyma-oy qanday o'zgargan: qancha qo'shilgan, qanchasi to'langan va oy oxirida qancha qolgan.": "Как долг менялся по месяцам: сколько добавилось, сколько оплачено и сколько осталось в конце месяца.",
  "Butun kompaniya bo'yicha — bu jadval filialga bo'linmaydi.": "По всей компании — эта таблица не делится по филиалам.",
  "O'quvchi o'qishni tashlagani uchun undirilmaydigan deb belgilangan qarzlar.": "Долги, признанные невзыскиваемыми, потому что ученик бросил учёбу.",
  "Markaz o'quvchilar to'lamagan darslar uchun ustozlarga pul to'lab bergan. Bu yerda o'sha pul kimdan undirilishi kerakligi ko'rinadi.": "Центр заплатил преподавателям за занятия, которые ученики не оплатили. Здесь видно, с кого нужно взыскать эти деньги.",
  "Davr tanlovi qaysi oydagi darslar hisobga olinishini belgilaydi — o'quvchining qarz summasi o'zgarmaydi.": "Выбор периода определяет, занятия какого месяца учитываются, — сумма долга ученика не меняется.",
  "Butun davr": "Весь период",
  "Markaz qoplagan, hali qaytmagan dars yo'q — hammasi undirilgan.": "Нет занятий, покрытых центром и ещё не возвращённых, — всё взыскано.",
  "{month}da markaz qoplagan dars yo'q — bu oyda hali dars o'tilmagan yoki hamma o'quvchi to'lagan.": "За {month} нет занятий, покрытых центром, — в этом месяце ещё не было занятий или все ученики оплатили.",
