  "Xabar berish": "Уведомить",
  "«Pulingizni olib keting» — markazga o'tkazishdan oldin kamida bir marta.": "«Заберите свои деньги» — хотя бы один раз до перевода на счёт центра.",
  "Bot ulanmagan — qo'ng'iroq qiling va belgilang.": "Бот не подключён — позвоните и отметьте.",
