  "Eng pastdan tartiblangan. Ro'yxatda yo'q qatorlar ham umumiy foizga kiradi, shuning uchun kesimlar yig'indisi umumiy sonlarga teng.": "Отсортировано от самой низкой. Строки, которых нет в списке, тоже входят в общий процент, поэтому сумма разрезов равна общим цифрам.",
  "Ustoz — guruhning hozirgi ustozi; o'rinbosar o'tgan dars guruhning o'z ustoziga yoziladi.": "Преподаватель — текущий преподаватель группы; занятие, проведённое заменяющим, записывается на собственного преподавателя группы.",
