  "Shundan {n} tasining oyi hali hisoblanmagan, summaga kirmadi.": "Из них {n} — за ещё не рассчитанный месяц, в сумму не вошли.",
  "{hidden} ta qatorda yozuv kam ({min} tadan kam), ro'yxatda yo'q.": "Строк с малым числом записей (меньше {min}): {hidden} — в списке их нет.",
  "{n} o'quvchi 3 va undan ko'p darsga ketma-ket sababsiz kelmadi.": "Учеников, пропустивших без причины 3 и более занятий подряд: {n}.",
