  "Bu bugungi holat, tanlangan davrga bog'liq emas. Hisob biroz farq qiladi: oldindan aytilgan sababsiz yo'qlik kelmagan hisoblanadi, markaz bekor qilgan darslar ko'rinmaydi, faqat faol o'quvchilar sanaladi.": "Это состояние на сегодня, оно не зависит от выбранного периода. Подсчёт немного отличается: заранее объявленное отсутствие без уважительной причины считается неявкой, занятия, отменённые центром, не видны, учитываются только активные ученики.",
