  "Sana va soat, narxni belgilang. Boshqa parametrlarni keyin sozlash mumkin.": "Укажите дату, время и цену. Остальные параметры можно настроить позже.",
  "Masalan: IELTS Mock — Yanvar 2026": "Например: IELTS Mock — январь 2026",
  "Imtihon haqida qo'shimcha ma'lumot": "Дополнительная информация об экзамене",
  "Imtihon sanasi": "Дата экзамена",
  "Imtihon vaqtlari": "Время экзамена",
  "Bir nechta vaqt qo'shsangiz, botda ro'yxatdan o'tuvchi vaqtni tanlaydi. Birinchisi asosiy sana-vaqt.": "Если добавить несколько вариантов времени, регистрирующийся выберет время в боте. Первое — основные дата и время.",
  "Ro'yxatga olish muddati (ixtiyoriy)": "Срок регистрации (необязательно)",
  "Belgilangan vaqt kelganda ro'yxat avtomatik yopiladi.": "В указанное время регистрация закроется автоматически.",
  "0 = bepul": "0 = бесплатно",
  "Click/Payme orqali ID'ga to'lanadi": "Оплачивается по ID через Click/Payme",
  "DaF o'quvchi narxi (ixtiyoriy)": "Цена для учеников DaF (необязательно)",
  "Bo'sh = to'liq narx": "Пусто = полная цена",
  "Markazimiz o'quvchilariga chegirmali narx. Chetlatilgan va arxivdagi o'quvchilar to'liq narx to'laydi. Bo'sh qoldirilsa, hamma to'liq narx to'laydi.": "Цена со скидкой для учеников нашего центра. Исключённые и архивные ученики платят полную цену. Если оставить пустым, все платят полную цену.",
  "Taklif etiladigan darajalar (ixtiyoriy)": "Предлагаемые уровни (необязательно)",
  "Tanlangan darajalar botda tugma sifatida chiqadi; ro'yxatdan o'tuvchi bittasini tanlaydi.": "Выбранные уровни появятся в боте кнопками; регистрирующийся выберет один.",
  "Bo'limlar va ballar": "Разделы и баллы",
  "Kamida 1 ta": "Минимум 1",
  "Nom": "Название",
  "Maks": "Макс.",
  "O'tish": "Проходной",
  "Masalan: Hören": "Например: Hören",
  "Kamida 1 ta bo'lim qoldirish kerak": "Нужно оставить хотя бы один раздел",
  "Bo'lim qo'shish": "Добавить раздел",
  "Goethe B1+ modular formati: har bo'lim 100 dan, o'tish 60. O'tish balli ixtiyoriy.": "Модульный формат Goethe B1+: каждый раздел из 100, проходной 60. Проходной балл необязателен.",
  "Bu imtihon bepul bo'ladimi?": "Этот экзамен будет бесплатным?",
  "Narx kiritilmadi. Agar shunday davom etsangiz, imtihon bepul bo'lib yaratiladi va bot ro'yxatdan o'tganlardan to'lov so'ramaydi.": "Цена не указана. Если продолжить, экзамен будет создан бесплатным, и бот не будет просить оплату у зарегистрировавшихся.",
  "Imtihon pullik bo'lishi kerak bo'lsa — bekor qiling va \"Narx\" maydonini to'ldiring.": "Если экзамен должен быть платным — отмените и заполните поле «Цена».",
  "Ha, bepul bo'lsin": "Да, бесплатно",
  "Imtihon yangilandi": "Экзамен обновлён",
  "Imtihonni tahrirlash": "Редактировать экзамен",
  "Barcha maydonlarni o'zgartirish mumkin. Ishtirokchi bo'lsa, forma o'zgarishi ularning javoblariga ta'sir qilmaydi.": "Все поля можно изменить. Если участники уже есть, изменения формы не затронут их ответы.",
  "Bir nechta vaqt = botda tanlov. Birinchisi asosiy sana-vaqt.": "Несколько вариантов времени = выбор в боте. Первое — основные дата и время.",
  "Ro'yxatga olish muddati": "Срок регистрации",
  "Markaz o'quvchilariga chegirmali narx.": "Цена со скидкой для учеников центра.",
  "Taklif etiladigan darajalar": "Предлагаемые уровни",
  "Botda tugma sifatida chiqadi; foydalanuvchi bittasini tanlaydi.": "Появятся в боте кнопками; пользователь выберет один.",
  "Vaqt qo'shilmagan.": "Время не добавлено.",
