  "Vaqt qo'shish": "Добавить время",
  "Imtihonni yuklashda xatolik": "Ошибка при загрузке экзамена",
  "Holat o'zgartirildi": "Статус изменён",
  "PDF yaratildi, natijalar ishtirokchilarga yuborilmoqda": "PDF создан, результаты отправляются участникам",
  "PDF yaratishda xatolik": "Ошибка при создании PDF",
