  "Imtihon topilmadi": "Экзамен не найден",
  "Ulashish": "Поделиться",
  "E'lon qilingan, lekin natijalar PDF'i yaratilmagan — yaratib, ishtirokchilarga yuborish": "Объявлено, но PDF с результатами не создан — создать и отправить участникам",
  "PDF yaratib yuborish": "Создать и отправить PDF",
  "Natijalar PDFini yangi yorliqda ochish": "Открыть PDF с результатами в новой вкладке",
  "Ishtirokchilar ({n})": "Участники ({n})",
  "Imtihonni o'chirish": "Удалить экзамен",
  "\"{title}\" imtihoni o'chiriladi. Ishtirokchilar va natijalar ham arxivlanadi (yo'qotilmaydi), ularning to'lov havolalari ishlamay qoladi. To'lagan ishtirokchi bo'lsa, avval ularni «Ishtirokchilar» bo'limidan pul qaytarilganini tasdiqlab o'chiring.": "Экзамен «{title}» будет удалён. Участники и результаты тоже уйдут в архив (не потеряются), их ссылки на оплату перестанут работать. Если есть оплатившие участники, сначала удалите их во вкладке «Участники», подтвердив возврат денег.",
  "Baholash": "Оценивание",
  "Keyingi: {action}": "Далее: {action}",
  "Yoki: {action}": "Или: {action}",
  "Imtihon jarayoni yakunlandi.": "Экзамен завершён.",
  "Ro'yxatga olish havolasi": "Ссылка для регистрации",
  "Ushbu havolani ulashing — foydalanuvchi havolaga bosib Telegram bot orqali \"{title}\" imtihoniga ro'yxatga olinadi.": "Поделитесь этой ссылкой — нажав на неё, пользователь зарегистрируется на экзамен «{title}» через Telegram-бот.",
  "Imtihon holati \"Ro'yxat ochiq\" emas — havola ishlamaydi. Avval imtihonni \"Ro'yxat ochiq\" holatiga o'tkazing.": "Статус экзамена не «Регистрация открыта» — ссылка не работает. Сначала переведите экзамен в статус «Регистрация открыта».",
  "QR kodni skanerlash orqali ham havolani ochish mumkin": "Ссылку также можно открыть, отсканировав QR-код",
  "Ro'yxat yopiladi": "Регистрация закрывается",
