  "Holatni sahifa tepasidagi bosqichlar qatoridan o'zgartiring.": "Измените статус в строке этапов вверху страницы.",
  "Ishtirokchi": "Участник",
  "Qizil — bo'limning o'tish balidan past": "Красный — ниже проходного балла раздела",
  "yashil — o'tish baliga yetgan": "зелёный — проходной балл набран",
  "Ballar saqlangach «O'rin» ustunini yuqoridagi tugma bilan qayta hisoblang.": "После сохранения баллов пересчитайте столбец «Место» кнопкой выше.",
  "Ball noto'g'ri kiritildi: {subject}": "Балл введён неверно: {subject}",
