  "Och chiziq — ilovani ochganlar, to'q chiziq — faol kun bo'lganlar": "Светлая линия — открывшие приложение, тёмная — с активным днём",
  "Ikki chiziq orasidagi bo'shliq — «ochdi, lekin ishlamadi».\nDavr 7 kun tanlansa ham grafik 30 kun ko'rsatadi: tendensiya 7 kunda ko'rinmaydi.": "Промежуток между линиями — «открыл, но не занимался».\nДаже если выбран период 7 дней, график показывает 30 дней: за 7 дней тенденцию не видно.",
