  "Har bir unit va bo'lim bo'yicha nechta so'z, gap, ibora va dialog qatori bor — va ulardan qanchasida ovoz yoki rasm tayyor. Bazadan avtomatik.": "Сколько слов, предложений, фраз и реплик диалога в каждом юните и разделе — и для скольких из них готовы аудио или изображение. Автоматически из базы.",
