  "{n} ta savol": "Вопросов: {n}",
  "Savol formatlari": "Форматы вопросов",
  "shu bo'lim + shu unitdagi undan oldingi barcha bo'limlar materiali birlashtirilgan (dvigatel chalg'ituvchilarni ham shu puldan oladi). Shuning uchun boshqa yorliqdagi «Material» ro'yxatida (faqat shu bo'lim) yo'q so'z, gap yoki ibora bu yerda ko'rinishi mumkin — bu xato emas.": "материал этого раздела и всех предыдущих разделов юнита объединён (движок берёт оттуда и отвлекающие варианты). Поэтому здесь могут встретиться слова, предложения или фразы, которых нет в списке на вкладке «Материал» (только этот раздел), — это не ошибка.",
  "Savollar olinmadi": "Не удалось получить вопросы",
  "Bu bo'limdan hali bironta savol qurib bo'lmaydi — shu bo'lim va undan oldingi bo'limlar materiali (so'z, gap, ibora yoki dialog) birgalikda yetarli emas.": "Из этого раздела пока нельзя построить ни одного вопроса — материала этого и предыдущих разделов (слов, предложений, фраз или диалогов) вместе недостаточно.",
  "Diqqat: boshqa yorliqdagi «Material» ro'yxati faqat shu bo'limni ko'rsatadi (yuqoridagi «Ko'lam» yorlig'iga qarang) — kamchilik shu unitning oldingi bo'limida bo'lishi ham mumkin, uni ko'rish uchun «Media» ro'yxatidan o'sha bo'lim sahifasiga o'ting.": "Внимание: список на вкладке «Материал» показывает только этот раздел (см. «Область» выше) — недостаток может быть и в предыдущем разделе этого юнита; чтобы его увидеть, откройте страницу того раздела из списка «Медиа».",
