  "Davomat qanday belgilanadi?": "Как отмечается посещаемость?",
  "Davomat darsda o'qituvchingiz tomonidan belgilanadi. Uni Bosh sahifada va «Davomat» bo'limida kuzatib borishingiz mumkin.": "Посещаемость отмечает ваш преподаватель на занятии. Следить за ней можно на главной странице и в разделе «Посещаемость».",
  "Balansim manfiy bo'lsa nima bo'ladi?": "Что, если баланс отрицательный?",
  "Manfiy balans qarzdorlikni bildiradi. Darslarni davom ettirish uchun iltimos balansni to'ldiring.": "Отрицательный баланс означает задолженность. Чтобы продолжать занятия, пожалуйста, пополните баланс.",
  "Jadvalim va davomatim qayerda?": "Где моё расписание и посещаемость?",
  "Bugungi darslaringiz Bosh sahifada, butun hafta «Jadval» bo'limida. Davomat foizi Bosh sahifada, batafsil tarixi «Davomat» bo'limida.": "Сегодняшние занятия — на главной странице, вся неделя — в разделе «Расписание». Процент посещаемости — на главной странице, подробная история — в разделе «Посещаемость».",
  "Profil rasmini qanday o'zgartiraman?": "Как сменить фото профиля?",
  "Profil sahifasini oching (telefonda «Ko'proq» ichida, kompyuterda yon menyuning tepasida), rasm ustiga bosing va yangi rasm tanlang.": "Откройте профиль (на телефоне — в разделе «Ещё», на компьютере — вверху бокового меню), нажмите на фото и выберите новое.",
  "Nemis tili o'quv markazi": "Центр изучения немецкого языка",
  "Markaz haqida": "О центре",
  "DAF Sprachzentrum — nemis tilini zamonaviy uslublarda o'rgatuvchi markaz. Ushbu portal orqali jadvalingizni, davomatingizni va to'lovlaringizni bir joyda kuzatib borasiz.": "DAF Sprachzentrum — центр, где немецкий язык преподают по современным методикам. В этом портале вы следите за расписанием, посещаемостью и платежами в одном месте.",
  "Portal versiyasi {version}": "Версия портала {version}",
